      <div class="sidebar-bottom"><details class="sidebar-tools"><summary><img class="action-icon" src="./icons/settings.svg" alt=""><span class="nav-label">Tools & exports</span></summary><a href="../api/life/?action=backup" title="Download full private backup"><svg class="nav-icon" aria-hidden="true" focusable="false" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"> <path d="M16.44 8.90039C20.04 9.21039 21.51 11.0604 21.51 15.1104V15.2404C21.51 19.7104 19.72 21.5004 15.25 21.5004H8.73998C4.26998 21.5004 2.47998 19.7104 2.47998 15.2404V15.1104C2.47998 11.0904 3.92998 9.24039 7.46998 8.91039" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/> <path d="M12 15.0001V3.62012" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/> <path d="M15.3499 5.85L11.9999 2.5L8.6499 5.85" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/> </svg><span class="nav-label">Full backup</span></a><a href="../api/life/?action=calendar-export" title="Export dated tasks"><svg class="nav-icon" aria-hidden="true" focusable="false" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"> <g clip-path="url(#clip0_4418_9971)"> <path d="M8 2V5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round"/> <path d="M16 2V5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round"/> <path d="M3.5 9.08984H20.5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round"/> <path d="M21 8.5V17C21 20 19.5 22 16 22H8C4.5 22 3 20 3 17V8.5C3 5.5 4.5 3.5 8 3.5H16C19.5 3.5 21 5.5 21 8.5Z" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round"/> <path d="M15.6947 13.6992H15.7037" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> <path d="M15.6947 16.6992H15.7037" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> <path d="M11.9955 13.6992H12.0045" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> <path d="M11.9955 16.6992H12.0045" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> <path d="M8.29431 13.6992H8.30329" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> <path d="M8.29431 16.6992H8.30329" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> </g> <defs> <clipPath id="clip0_4418_9971"> <rect width="24" height="24" fill="currentColor"/> </clipPath> </defs> </svg><span class="nav-label">Calendar export</span></a><a href="../api/life/?action=export" id="export" aria-label="Export my data" title="Export my data"><svg class="nav-icon" aria-hidden="true" focusable="false" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"> <path d="M16.44 8.90039C20.04 9.21039 21.51 11.0604 21.51 15.1104V15.2404C21.51 19.7104 19.72 21.5004 15.25 21.5004H8.73998C4.26998 21.5004 2.47998 19.7104 2.47998 15.2404V15.1104C2.47998 11.0904 3.92998 9.24039 7.46998 8.91039" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/> <path d="M12 15.0001V3.62012" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/> <path d="M15.3499 5.85L11.9999 2.5L8.6499 5.85" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/> </svg><span class="nav-label">Export my data</span></a></details><button id="logout" aria-label="Sign out" title="Sign out"><svg class="nav-icon" aria-hidden="true" focusable="false" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"> <path d="M17.4399 14.62L19.9999 12.06L17.4399 9.5" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round"/> <path d="M9.75977 12.0596H19.9298" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round"/> <path d="M11.7598 20C7.33977 20 3.75977 17 3.75977 12C3.75977 7 7.33977 4 11.7598 4" stroke="currentColor" stroke-width="1.5" stroke-miterlimit="10" stroke-linecap="round" stroke-linejoin="round"/> </svg><span class="nav-label">Sign out</span></button></div>
    </aside>
    <main>
      <header class="topbar"><button id="nav-open" class="nav-icon-button" aria-label="Open navigation" aria-expanded="false" aria-controls="planner-navigation"><svg class="nav-icon" aria-hidden="true" focusable="false" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg"> <g clip-path="url(#clip0_4418_9850)"> <path d="M3 7H21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/> <path d="M3 12H21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/> <path d="M3 17H21" stroke="currentColor" stroke-width="1.5" stroke-linecap="round"/> </g> <defs> <clipPath id="clip0_4418_9850"> <rect width="24" height="24" fill="currentColor"/> </clipPath> </defs> </svg></button><p>My Life <span>/</span> <span id="breadcrumb">My board</span></p><span id="save-status" role="status">All changes saved</span></header>
      <section class="page-heading"><div><p class="eyebrow" id="page-eyebrow">A SPACE TO MOVE FORWARD</p><h1 id="page-title">Your life, <em>in motion.</em></h1><p id="page-description">Capture the thought. Take the next step. Keep the bigger picture close.</p></div><button class="primary" id="new-task">+ New task</button></section>
      <div class="board-picker"><label>Board<select id="board-select" aria-label="Personal board"></select></label><button id="new-board">+ New board</button><button id="rename-board">Rename board</button></div><section id="sprint-panel" class="sprint-panel" hidden><div><p class="eyebrow">THIS WEEK'S INTENTION</p><label for="sprint-goal">What would make this a good week?</label><textarea id="sprint-goal" rows="2" maxlength="2000" placeholder="Write one clear sprint goal…"></textarea><button id="save-goal" class="primary">Save sprint goal</button></div><div><div class="week-switch"><button id="previous-week" aria-label="Previous week">←</button><span id="week-range"></span><button id="next-week" aria-label="Next week">→</button></div><p id="sprint-progress"></p><label>Weekly capacity (hours)<input id="week-capacity" type="number" min="0" max="168" step="0.5" value="0"></label><p id="capacity-summary"></p><button id="save-capacity">Save capacity</button><button id="choose-tasks">Choose sprint tasks</button><button id="current-week">Back to this week</button></div></section>
      <section class="toolbar" aria-label="Board filters"><label class="search"><svg class="search-icon" aria-hidden="true" width="24" height="24" viewBox="0 0 24 24" fill="none" xmlns="http://www.w3.org/2000/svg">
<path d="M11 20C15.9706 20 20 15.9706 20 11C20 6.02944 15.9706 2 11 2C6.02944 2 2 6.02944 2 11C2 15.9706 6.02944 20 11 20Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
<path d="M18.9299 20.6898C19.4599 22.2898 20.6699 22.4498 21.5999 21.0498C22.4499 19.7698 21.8899 18.7198 20.3499 18.7198C19.2099 18.7098 18.5699 19.5998 18.9299 20.6898Z" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
</svg>
<input id="search" type="search" placeholder="Find a task…" aria-label="Search tasks"></label><label><span class="sr-only">Priority filter</span><select id="priority-filter"><option value="">All priorities</option><option value="high">High priority</option><option value="normal">Normal priority</option><option value="low">Low priority</option></select></label><label><span class="sr-only">Label filter</span><select id="label-filter"><option value="">All labels</option></select></label><button id="clear-filters" hidden>Clear filters</button><span id="task-count"></span><button id="new-list">+ Add list</button><label class="mobile-list"><span class="sr-only">Visible list</span><select id="mobile-list"></select></label></section>
      <div id="board" class="board" aria-label="Task board"></div>
      <div id="archive" hidden></div><section id="companion" hidden aria-label="AI planning companion"></section><section id="thinking" hidden aria-label="Notes and mind map"></section><section id="routines" hidden aria-label="Recurring routines"></section><section id="accountability" hidden aria-label="Accountability partners"></section><section id="goals" hidden aria-label="Goals and reviews"></section><section id="planning" hidden aria-label="Daily and calendar planning"></section>
      <p class="board-footnote" id="board-footnote">Swipe across lists. Drag a card or its grip to move it, or open the task and choose its list.</p>
      <div id="page-error" class="error" role="alert" hidden></div>
      <button id="reload" class="reload" hidden>Load latest board — keep my draft</button>
    </main>
  </div>
  <dialog id="task-dialog" aria-labelledby="task-dialog-title">
    <form id="task-form"><div class="dialog-heading"><div><p class="eyebrow">ONE NEXT STEP</p><h2 id="task-dialog-title">New task</h2></div><button type="button" data-close aria-label="Close task">×</button></div>
      <input type="hidden" name="id"><input type="hidden" name="position" value="1">
      <p class="task-step-label" id="task-step-label">1 of 3 · The essentials</p>
      <section data-task-step="0"><label>What do you want to do?<input name="title" required maxlength="200" placeholder="Your next step"></label><div class="field-row"><label>List<select name="listId"></select></label><label>Priority<select name="priority"><option value="normal">Normal</option><option value="high">High</option><option value="low">Low</option></select></label></div></section>
      <section data-task-step="1" hidden><label>Due date<input name="dueDate" type="date"></label><label>Linked goal<select name="goalId"><option value="">No linked goal</option></select></label><label>Notes<textarea name="notes" rows="3" maxlength="20000" placeholder="A little context, if you need it"></textarea></label></section>
      <section data-task-step="2" hidden><label>Time needed (minutes)<input name="effortMinutes" type="number" min="0" max="10080" value="0"></label><label>Labels<input name="labels" maxlength="410" placeholder="Work, Personal, Learning"></label><label>What's in the way?<textarea name="blocker" rows="2" maxlength="2000" placeholder="Optional"></textarea></label><details class="task-more"><summary>Checklist and more</summary><label>Depends on<select name="dependencies" multiple aria-label="Task dependencies"></select></label><div class="checklist-heading"><h3>Checklist</h3><button type="button" id="add-checklist">+ Add item</button></div><div id="checklist"></div><label class="checkbox-label"><input name="inSprint" type="checkbox"> Plan for this week</label><section id="task-attachments"><h3>Private attachments</h3><div id="attachment-list"></div><label>Attach a file<input id="attachment-file" type="file" accept="image/jpeg,image/png,image/webp,application/pdf,text/plain"></label><button id="upload-attachment" type="button">Upload attachment</button><small>Save a new task first. Maximum 5 MB. Images, PDF and text.</small></section></details></section><div class="task-step-actions"><button type="button" id="task-back" hidden>Back</button><button type="button" id="task-next">Next · optional details</button></div><p id="task-error" class="error" role="alert"></p><button type="button" data-reload hidden>Load latest board — keep my draft</button><div class="dialog-actions"><button type="button" id="archive-task" class="danger" hidden><img class="action-icon" src="./icons/archive.svg" alt=""> Archive task</button><button type="button" data-close>Cancel</button><button type="submit" class="primary">Save task</button></div>
    </form>
  </dialog>
  <dialog id="board-dialog" aria-labelledby="board-dialog-title"><form id="board-form"><div class="dialog-heading"><h2 id="board-dialog-title">Your board</h2><button type="button" data-close aria-label="Close board">×</button></div><input name="id" type="hidden"><label>Board name<input name="name" required maxlength="80"></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary">Save board</button></div></form></dialog><dialog id="list-dialog" aria-labelledby="list-dialog-title"><form id="list-form"><div class="dialog-heading"><h2 id="list-dialog-title">Add list</h2><button type="button" data-close aria-label="Close list">×</button></div><input type="hidden" name="id"><label>List name<input name="name" required maxlength="80"></label><p id="list-error" class="error" role="alert"></p><button type="button" data-reload hidden>Load latest board — keep my draft</button><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save list</button></div></form></dialog>
  <dialog id="sprint-dialog" aria-labelledby="sprint-dialog-title"><form id="sprint-form"><div class="dialog-heading"><h2 id="sprint-dialog-title">Choose sprint tasks</h2><button type="button" data-close aria-label="Close sprint selection">×</button></div><p>Choose what you will focus on. These remain the same tasks on your board.</p><div id="sprint-choices"></div><p id="sprint-error" class="error" role="alert"></p><button type="button" data-reload hidden>Load latest board — keep my draft</button><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save selection</button></div></form></dialog>
  <dialog id="schedule-dialog" aria-labelledby="schedule-title"><form id="schedule-form"><div class="dialog-heading"><h2 id="schedule-title">Make time for a task</h2><button type="button" data-close aria-label="Close scheduling">×</button></div><p>A work block is time you plan to spend. It does not change the task deadline. All times use Africa/Lagos.</p><label>Task<select name="taskId" required></select></label><div class="field-row"><label>Work date<input name="date" type="date" required></label><label>Start time<input name="time" type="time" required value="09:00"></label></div><label>Duration in minutes<input name="minutes" type="number" min="5" max="1440" required value="60"></label><p id="schedule-error" class="error" role="alert"></p><button type="button" data-reload hidden>Load latest board — keep my draft</button><div class="dialog-actions"><button type="button" id="unschedule-task" class="danger">Remove work block</button><button type="button" data-close>Cancel</button><button type="submit" class="primary">Save work block</button></div></form></dialog>
  <dialog id="goal-dialog" aria-labelledby="goal-title"><form id="goal-form"><div class="dialog-heading"><h2 id="goal-title">A bigger intention</h2><button type="button" data-close aria-label="Close goal">×</button></div><input type="hidden" name="id"><label>Goal<input name="title" required maxlength="200"></label><div class="field-row"><label>Period type<select name="type"><option value="quarter">Quarter</option><option value="month">Month</option><option value="week">Weekly sprint</option><option value="adhoc">Ad hoc</option></select></label><label>Period<input name="period" placeholder="2026-Q4 / 2026-10 / Monday date" maxlength="10"></label></div><label>Contributes to<select name="parentId"></select></label><label>Life area<input name="category" list="life-areas" maxlength="60" required><datalist id="life-areas"><option value="Personal"><option value="Work"><option value="Family"><option value="Health"><option value="Learning"><option value="Volunteering"><option value="Applications"></datalist><small>Choose an area or type your own.</small></label><label>What does success look like?<textarea name="notes" rows="4" maxlength="10000"></textarea></label><label class="checkbox-label"><input type="checkbox" name="completed"> Mark goal complete</label><p id="goal-error" class="error" role="alert"></p><button type="button" data-reload hidden>Load latest board — keep my draft</button><div class="dialog-actions"><button type="button" data-close>Cancel</button><button class="primary" type="submit">Save goal</button></div></form></dialog>
  <dialog id="confirm-dialog" aria-labelledby="confirm-title"><div class="dialog-heading"><h2 id="confirm-title">Archive this item?</h2></div><p>You can restore it from Archive.</p><div class="dialog-actions"><button id="confirm-cancel">Cancel</button><button id="confirm-yes" class="primary">Archive</button></div></dialog>
</body></html>
